"""Embedding: turn a list of text chunks into vectors with the OpenAI embeddings API.

The texts are read from one configured field of the inbound data, embedded in
batches, and returned in input order next to the texts themselves, so a vector
store downstream can store each vector with the text it came from. The OpenAI
key is the ``openai_api_key`` secret bound on the node; it is sent only in the
request header and never logged.
"""

import httpx
import perceivo

_EMBEDDINGS_URL = "https://api.openai.com/v1/embeddings"
_MODELS = ("text-embedding-3-small", "text-embedding-3-large", "text-embedding-ada-002")
_DEFAULT_MODEL = "text-embedding-3-small"
_DEFAULT_TEXTS_FIELD = "chunks"
_REQUEST_TIMEOUT_SECONDS = 60.0
# Inputs per request; well inside the API's per-request limit.
_BATCH_SIZE = 96
_ABSENT = object()


def _lookup(data, path: str):
    """The value at a dotted path inside nested dicts, or _ABSENT."""
    value = data
    for part in path.split("."):
        if not isinstance(value, dict) or part not in value:
            return _ABSENT
        value = value[part]
    return value


def _texts(data, request_data: dict, field: str) -> list:
    """The strings to embed, from the inbound artifact's data or request_data.

    The artifact data may be a JSON object carrying the field, a bare list, or a
    single string; otherwise the field is read from request_data.
    """
    if isinstance(data, list):
        found = data
    elif isinstance(data, str) and data.strip():
        found = [data]
    else:
        found = _lookup(data, field) if isinstance(data, dict) else _ABSENT
        if found is _ABSENT:
            found = _lookup(request_data, field)
    if found is _ABSENT:
        raise ValueError(
            f"No texts found at {field!r}. Set Texts Field to where the incoming data "
            f"carries the list of texts. Fields received: {sorted(request_data)}."
        )
    if isinstance(found, str):
        found = [found]
    if not isinstance(found, list):
        raise ValueError(f"{field!r} holds a {type(found).__name__}; it must be a list of texts.")
    return [item if isinstance(item, str) else str(item) for item in found]


async def _embed_batch(client: httpx.AsyncClient, api_key: str, model: str, texts: list) -> list:
    """Embed one batch and return its vectors in input order."""
    response = await client.post(
        _EMBEDDINGS_URL,
        headers={"Authorization": f"Bearer {api_key}"},
        json={"model": model, "input": texts},
    )
    if response.status_code != 200:
        # The error type and code identify the failure without echoing the body.
        try:
            error = response.json().get("error") or {}
        except ValueError:
            error = {}
        raise RuntimeError(
            f"OpenAI embeddings request failed: HTTP {response.status_code} "
            f"(type={error.get('type') or 'unknown'}, code={error.get('code') or 'unknown'})."
        )
    items = sorted(response.json()["data"], key=lambda item: item["index"])
    if len(items) != len(texts):
        raise RuntimeError(f"OpenAI returned {len(items)} vectors for {len(texts)} texts.")
    return [item["embedding"] for item in items]


@perceivo.agent
async def embedding(input: perceivo.primitives.AgentInput) -> perceivo.primitives.AgentOutput:
    """Embed the inbound texts and pass every inbound field through.

    An empty list is a valid input and yields no vectors without calling the
    API. A missing field, a missing key or an unknown model raises ValueError;
    a failed API call raises RuntimeError, so a partial or failed embedding is
    never passed downstream as a result.
    """
    request_data = input.request_data or {}

    model = str(perceivo.params.get("model", _DEFAULT_MODEL) or _DEFAULT_MODEL).strip()
    if model not in _MODELS:
        raise ValueError(f"Embedding Model is {model!r}. Choose one of: {', '.join(_MODELS)}.")
    field = str(perceivo.params.get("texts_field", _DEFAULT_TEXTS_FIELD) or "").strip()
    if not field:
        raise ValueError("Texts Field is empty. Name the field that carries the texts, e.g. chunks.")

    artifact_data = input.artifact.data if input.artifact is not None else None
    texts = _texts(artifact_data, request_data, field)

    vectors = []
    if texts:
        api_key = await perceivo.secrets.get("openai_api_key", None)
        if not api_key:
            raise ValueError(
                "The openai_api_key secret is not bound. Bind an OpenAI API key to this node."
            )
        async with httpx.AsyncClient(timeout=_REQUEST_TIMEOUT_SECONDS) as client:
            for start in range(0, len(texts), _BATCH_SIZE):
                vectors.extend(await _embed_batch(client, api_key, model, texts[start:start + _BATCH_SIZE]))
    else:
        perceivo.log.warning("Embedding: the texts list is empty; nothing embedded", field=field)

    dimensions = len(vectors[0]) if vectors else 0
    perceivo.log.info("Embedding complete", model=model, count=len(vectors), dimensions=dimensions)

    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data={"embedding_count": len(vectors), "dimensions": dimensions, "embedding_model": model},
            mime_type="application/json",
        ),
        response_data={
            **request_data,
            "embeddings": vectors,
            "texts": texts,
            "embedding_count": len(vectors),
            "embedding_model": model,
            "dimensions": dimensions,
        },
    )
